  g.fillStyle='#b49d7f';g.beginPath();g.ellipse(900,1715,100,48,0,0,Math.PI*2);g.fill();g.fillStyle='#edf0e5';g.fillRect(870,1699,36,24);g.fillStyle='#627675';g.fillRect(912,1702,24,17);add('sharedTable',800,1667,200,96);for(const x of[760,1020]){g.fillStyle='#7c8c77';g.fillRect(x,1695,48,47);g.fillStyle='#b2c1a2';g.fillRect(x+5,1700,38,31);add('loungeChair',x,1695,48,47)}
