 function buildFloor(){blocked.clear();objects.length=0;block(0,0,W,120);block(0,H-48,W,48);block(0,0,48,H);block(W-48,0,48,H);if(!artLoaded&&!officeImage.complete)return;drawRoomBase();
  if(currentFloor==='floor-1'||currentFloor==='floor-2'){
   roomShell(96,144,792,600,{tone:'#ccd5bf'});roomShell(1104,144,744,600,{tone:currentFloor==='floor-1'?'#d4d8c8':'#c4d4ce'});
   roomShell(96,816,792,588,{door:'top',tone:'#cbd5d1'});roomShell(1104,816,744,588,{door:'top',tone:currentFloor==='floor-1'?'#d6cbd2':'#cbd4c5'});
   if(currentFloor==='floor-2'){roomTable(650,1220)}
  }else{
   for(const pos of active(store.data.positions)){const s=spaceFor('position',pos.id);if(s?.floorId!==currentFloor)continue;const {x,y,w,h}=s.rect;roomShell(x,y,w,h-24,{tone:'#c6d3cf'});filingCabinet(x+w-70,y+90)}
   for(const o of active(store.data.organizations).filter(o=>o.parentId==='org-support')){const s=spaceFor('organization',o.id),{x,y,w,h}=s.rect;roomShell(x,y,w,h-24,{tone:'#d4d8c5'});filingCabinet(x+w-70,y+80)}
  }
  if(currentFloor==='floor-3')roomShell(1260,1120,480,216,{tone:'#d4d8c5'});
  renderAmenities();officeDetails();if(currentFloor==='floor-1')roomShell(1368,1488,456,360,{door:'top',tone:'#c8d4c2'});for(const c of active(store.data.characters).filter(c=>byId('spaces',c.spaceId)?.floorId===currentFloor))workstation(c);
  for(const [x,y]of[[1860,144],[1860,1360],[950,1380],[2470,1770]])officePlant(x,y);
  drawElevator();paintFloorLabels();if(!walkable(Math.floor(player.x/T),Math.floor(player.y/T))){player.x=floor().spawn.x;player.y=floor().spawn.y}artLoaded=true;drawMini();
 }

 function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
 function button(label,fn,cls=''){const b=node('button',label,cls);b.type='button';b.onclick=fn;return b}
 function link(type,id,label){return button(label||entity(type,id)?.name||'미정',()=>openEntity(type,id),'entity-link')}
 function row(label,value){const r=node('div',undefined,'org-row');r.append(node('dt',label));const dd=node('dd');if(value instanceof Node)dd.append(value);else dd.textContent=value||'미정';r.append(dd);return r}
 function typeLabel(type,e){return type==='organization'?types[e.type]:type==='position'?'직책 · '+(e.level==='headquarters_head'?'본부장':e.level):type==='workArea'?'업무 분류 · 조직 계층 미정':'직무'}
 function renderTree(){const list=$('#organizationTree');list.replaceChildren();function item(type,e,depth){const b=button(e.name,()=>openEntity(type,e.id),'org-tree-item'+(panelEntity?.id===e.id?' selected':''));b.style.setProperty('--depth',depth);b.append(node('small',typeLabel(type,e)));list.append(b)}function branch(o,depth){item('organization',o,depth);active(store.data.positions).filter(p=>p.organizationId===o.id).forEach(p=>item('position',p,depth+1));active(store.data.organizations).filter(c=>c.parentId===o.id).forEach(c=>branch(c,depth+1));active(store.data.workAreas).filter(a=>a.organizationId===o.id).forEach(a=>{item('workArea',a,depth+1);active(store.data.jobRoles).filter(r=>r.workAreaId===a.id).forEach(r=>item('jobRole',r,depth+2))});active(store.data.jobRoles).filter(r=>r.organizationId===o.id&&!r.workAreaId).forEach(r=>item('jobRole',r,depth+1))}
  for(const f of store.data.floors){list.append(node('h3',f.number+'층 · '+f.name));const roots=active(store.data.organizations).filter(o=>!o.parentId&&spaceFor('organization',o.id)?.floorId===f.id);if(f.id==='floor-3'){list.append(node('p','경영진 · 직책','tree-group'));active(store.data.positions).filter(p=>spaceFor('position',p.id)?.floorId===f.id).forEach(p=>item('position',p,0))}roots.forEach(o=>branch(o,0))}
 }
 function openEntity(type,id){const e=entity(type,id);if(!e)return;keys.clear();panelEntity={type,id};renderTree();const box=$('#organizationDetail');box.replaceChildren();box.append(node('span',typeLabel(type,e),'org-kind'),node('h2',e.name));const s=spaceFor(type,id),f=s&&byId('floors',s.floorId);const info=node('dl',undefined,'org-facts');info.append(row('유형',typeLabel(type,e)),row('배치 공간',f?f.number+'층 · '+s.name:'미정'));
  if(type==='organization'){info.append(row('상위 조직',e.parentId?link('organization',e.parentId):'미정'));if(e.id==='org-pmo')info.append(row('개발본부 산하 여부','미정'))}
  if(type==='position'){info.append(row('담당자',e.holderMemberId?byId('members',e.holderMemberId)?.name:'등록 예정'),row('담당 본부',e.organizationId?link('organization',e.organizationId):'미정'),row('보고 관계',e.reportsToPositionId?link('position',e.reportsToPositionId):'미정'),row('상세 담당 업무',e.responsibilities||'등록 예정'))}
  if(type==='workArea')info.append(row('소속 본부',link('organization',e.organizationId)),row('조직 계층','미정 · 팀·실·부문으로 확정하지 않음'));
  if(type==='jobRole'){info.append(row('소속 조직',e.organizationId?link('organization',e.organizationId):'미정'));if(e.workAreaId)info.append(row('업무 분류',link('workArea',e.workAreaId)))}
  info.append(row('업무 설명',e.description||'등록 예정'));if(e.specialties?.length)info.append(row('세부 전문 분야',e.specialties.join(' / ')));box.append(info);
  const children=type==='organization'?active(store.data.organizations).filter(o=>o.parentId===id):[],areas=type==='organization'?active(store.data.workAreas).filter(a=>a.organizationId===id):[],roles=active(store.data.jobRoles).filter(r=>type==='workArea'?r.workAreaId===id:type==='organization'?r.organizationId===id:false);
  function section(title,items,t){box.append(node('h3',title));const wrap=node('div',undefined,'org-chip-list');if(items.length)items.forEach(c=>wrap.append(link(t,c.id)));else wrap.append(node('p','등록 예정','org-empty'));box.append(wrap)}
  if(type==='organization'){const positions=active(store.data.positions).filter(p=>p.organizationId===id);if(positions.length)section('소속 직책',positions,'position');section('하위 조직',children,'organization');}if(areas.length)section('업무 분류',areas,'workArea');if(type!=='position')section('소속 직무',roles,'jobRole');
  if(type==='organization'&&e.specialties?.length)box.append(node('p','2D와 3D는 이 파트의 세부 전문 분야입니다. 별도 조직이 아닙니다.','org-note'));
  const avatars=store.data.characters.filter(c=>c.entityType===type&&c.entityId===id);if(avatars.length){box.append(node('h3','배치된 캐릭터'));for(const c of avatars){const person=c.memberId&&byId('members',c.memberId);box.append(node('p',(person?person.name:c.isPlaceholder?'조직 담당 캐릭터 · 실제 인물 등록 예정':c.name+' · 게임 내 동료')+' / '+(f?f.number+'층':'배치 공간 확인 예정'),'org-person'));}}
  box.append(node('h3','연결 데이터'));const counts=node('div',undefined,'org-records');for(const[k,label]of[['members','구성원·담당자'],['projects','프로젝트'],['tasks','업무·진행 상태'],['documents','문서·가이드'],['operationRecords','개발·운영 기록']]){const linked=store.data.entityLinks.filter(l=>l.sourceType===type&&l.sourceId===id&&l.targetType===k).length+(k==='members'?store.data.members.filter(m=>type==='organization'?m.organizationId===id:type==='position'?m.positionId===id:false).length:0);counts.append(node('div',label+' · '+(linked?linked+'건':'등록 예정')))}box.append(counts);const footer=node('p','고유 ID: '+e.id+' · '+(e.active===false?'비활성':'활성')+' · 표시 순서 '+e.sortOrder,'org-id');box.append(footer);if(f)box.append(button(f.number+'층 공간 보기',()=>{$('#companyPanel').close();switchFloor(f.id);selected={name:e.name,...s.interactionPoint};toast('위치를 표시했어요. 키보드로 이동해 Space를 누르세요.')},'org-locate'));
  if(!$('#companyPanel').open)$('#companyPanel').showModal();$('#companyPanelTitle').focus({preventScroll:true});
 }
 function hit(e){const p=worldPoint(e);return hitBoxes.slice().reverse().find(h=>p.x>=h.x&&p.x<=h.x+h.w&&p.y>=h.y&&p.y<=h.y+h.h)}
 canvas.addEventListener('click',e=>{if(performance.now()<(camera.suppressClickUntil||0)){e.stopImmediatePropagation();return}if(decorateMode||view!=='office')return;const point=worldPoint(e),avatar=scopedNPCs().slice().reverse().find(n=>Math.abs(n.x-point.x)<48&&point.y<n.y+15&&point.y>n.y-125);if(avatar){e.preventDefault();e.stopImmediatePropagation();const pos=avatar.memberId&&store.data.positions.find(p=>p.holderMemberId===avatar.memberId);openEntity(pos?'position':avatar.entityType,pos?.id||avatar.entityId);return}const h=hit(e);if(h){e.preventDefault();e.stopImmediatePropagation();openEntity(h.type,h.id)}},true);
 $('#companyToggle').onclick=()=>openEntity('organization',currentFloor==='floor-1'?'org-dev':currentFloor==='floor-2'?'org-publishing':'org-support');$('#closeCompany').onclick=()=>$('#companyPanel').close();
 document.querySelectorAll('[data-travel-floor]').forEach(b=>b.onclick=()=>switchFloor(b.dataset.travelFloor));
