 window.addEventListener('beforeunload',persistPosition);window.addEventListener('office-move-end',persistPosition);window.addEventListener('pagehide',persistPosition);document.addEventListener('visibilitychange',()=>{if(document.hidden)persistPosition()});
 // Clear example progress only when the user explicitly starts a new career; keep the company schema.
 const submit=$('#setupForm').onsubmit;$('#setupForm').onsubmit=e=>{submit(e);switchFloor('floor-1',{restore:false})};
 visit=id=>{if(currentFloor!=='floor-1')switchFloor('floor-1');goOffice();const f=originalFacilities.find(f=>f.id===id);if(f)selectTarget(f)};
 selectNPC=name=>{const c=store.data.characters.find(c=>c.legacyName===name||c.name===name);if(!c)return;const f=byId('spaces',c.spaceId)?.floorId;if(f&&currentFloor!==f)switchFloor(f);goOffice();const n=scopedNPCs().find(n=>n.id===c.id);if(n)selectTarget(n)};
 const baseDecoration=placeDecoration;placeDecoration=()=>{if(currentFloor==='floor-1'){baseDecoration();return}const original=state.decorations;state.decorations=store.data.session.decorationsByFloor[currentFloor]||[];baseDecoration();store.data.session.decorationsByFloor[currentFloor]=state.decorations;state.decorations=original;save();store.save()};
 window.CompanyUI={get floorId(){return currentFloor},get floorNumber(){return floor().number},activeNPCs:scopedNPCs,activeFacilities,drawSeatFront:n=>{const g=ctx,x=n.x,y=n.y;g.fillStyle='#35494b';g.beginPath();g.roundRect(x-29,y-37,58,34,9);g.fill();g.fillStyle='#76938b';g.beginPath();g.roundRect(x-24,y-33,48,25,6);g.fill();g.strokeStyle='#b5c9bb99';g.lineWidth=1;for(let mesh=0;mesh<3;mesh++){g.beginPath();g.moveTo(x-18,y-27+mesh*7);g.lineTo(x+18,y-27+mesh*7);g.stroke()}g.fillStyle='#51686a';g.fillRect(x-3,y-4,6,13);g.fillRect(x-28,y+7,56,4)},decorations:()=>currentFloor==='floor-1'?state?.decorations||[]:store.data.session.decorationsByFloor[currentFloor]||[],updateHUD:announce,buildMap:buildFloor,openEntity,elevator,switchFloor,getSnapshot:()=>JSON.parse(JSON.stringify(store.data)),transact:fn=>{const result=store.update(fn);buildFloor();renderTree();announce();return result}};
 buildMap=buildFloor;officeImage.onload=buildFloor;
 const saved=store.data.session.positionsByFloor[currentFloor];if(saved){player.x=saved.x;player.y=saved.y}else if(currentFloor!=='floor-1'){player.x=floor().spawn.x;player.y=floor().spawn.y}
 announce();if(officeImage.complete&&officeImage.naturalWidth)buildFloor();if(!walkable(Math.floor(player.x/T),Math.floor(player.y/T))){player.x=floor().spawn.x;player.y=floor().spawn.y}if(store.warning)toast(store.warning);
